import { createContext, useCallback, useEffect, useState } from 'react';
import metros from '../data/metros.json';

export interface UserLocation {
  /** "lat,lng" for Algolia's aroundLatLng; null → fall back to IP-based location. */
  latLng: string | null;
  label: string;
  source: 'browser' | 'preset' | 'ip';
}

// Every metro area in the data, with a center computed from its restaurants
// (generated by scripts/build-records.ts).
export const METRO_PRESETS: { label: string; latLng: string; restaurants: number }[] = metros;

const IP_FALLBACK: UserLocation = { latLng: null, label: 'Near you (approx.)', source: 'ip' };

/** Browser geolocation when allowed; otherwise Algolia estimates location from the IP. */
export function useUserLocation() {
  const [location, setLocation] = useState<UserLocation>(IP_FALLBACK);

  const requestBrowserLocation = useCallback(() => {
    if (!('geolocation' in navigator)) return;
    navigator.geolocation.getCurrentPosition(
      ({ coords }) =>
        setLocation({
          latLng: `${coords.latitude.toFixed(4)},${coords.longitude.toFixed(4)}`,
          label: 'Your location',
          source: 'browser',
        }),
      () => setLocation(IP_FALLBACK),
      { timeout: 8000, maximumAge: 10 * 60 * 1000 },
    );
  }, []);

  useEffect(requestBrowserLocation, [requestBrowserLocation]);

  const choosePreset = (label: string) => {
    const preset = METRO_PRESETS.find((p) => p.label === label);
    if (preset) setLocation({ label: preset.label, latLng: preset.latLng, source: 'preset' });
  };

  return { location, choosePreset, requestBrowserLocation };
}

/** Meters → "0.4 miles" / "12 miles" (singular for exactly 1). */
export function formatDistance(meters: number | undefined) {
  if (meters === undefined) return null;
  const miles = meters / 1609.34;
  const value = miles < 10 ? miles.toFixed(1) : String(Math.round(miles));
  return `${value} ${value === '1.0' ? 'mile' : 'miles'}`;
}

/**
 * The active search location, shared with cards and discovery rows.
 * With a metro picked, distances are measured from the metro's center point;
 * cards explain that in a tooltip and the slider names the place.
 */
export const LocationContext = createContext<UserLocation>(IP_FALLBACK);

/** Short name for labels: "New York / Tri-State Area" → "New York", "Dallas - Fort Worth" → "Dallas". */
export const placeName = (location: UserLocation) =>
  location.source === 'preset' ? location.label.split(/ \/ | - /)[0] : 'you';
